{"hypothesis":"Doubling or tripling the incumbent's inferred comb frequency while preserving local packet mass can expose a better support topology and gain at least 1e-5.","rationale":"The reported successes suggest that comb coherence and frequency matter more than coordinate-level polishing. This search infers packet periods, constructs mass-preserving finer combs, and searches mixtures with the incumbent using exact convolution polynomials; the original candidate remains the fallback.","source":"import time
import numpy as np
import scipy.fft as fft
from scipy.signal import oaconvolve
from scipy.optimize import minimize_scalar

PARAMS = {
    'time_fraction': (0.68, 0.3, 0.75),
    'period_count': (7, 2, 16),
    'support_threshold': (1e-7, 1e-10, 1e-3, 'log'),
}


def exact_score(f):
    c = oaconvolve(np.maximum(f, 0.0), np.maximum(f, 0.0), mode='full')
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    y = np.concatenate(([0.0], c, [0.0]))
    a, b = y[:-1], y[1:]
    num = float(np.sum((np.diff(x) / 3.0) * (a*a + a*b + b*b)))
    return num / ((np.sum(np.abs(c)) / (len(c)+1)) * np.max(np.abs(c)))


def bilinear(a, b):
    return (2.0*np.sum(a*b) + 0.5*np.sum(a[:-1]*b[1:]) + 0.5*np.sum(a[1:]*b[:-1])) / 3.0


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + budget_s * float(params['time_fraction'])
    if init is None:
        return {'values': [1.0]}
    original = np.maximum(np.asarray(init['values'], dtype=np.float64), 0.0)
    incumbent_score = exact_score(original)
    best_score = incumbent_score
    best = None
    n = len(original)
    if n < 16 or time.monotonic() >= deadline:
        return init
    f = original / np.sum(original)
    length = 2*n-1
    m = fft.next_fast_len(length, real=True)
    fs = fft.rfft(f, m, workers=1)
    base = fft.irfft(fs*fs, m, workers=1)[:length]
    q0 = bilinear(base, base)
    mask = original > original.max()*float(params['support_threshold'])
    starts = np.flatnonzero(mask & ~np.r_[False, mask[:-1]])
    periods = []
    if len(starts) > 2:
        gaps = np.diff(starts)
        vals, counts = np.unique(gaps[gaps >= 4], return_counts=True)
        for j in np.argsort(counts)[::-1][:int(params['period_count'])]:
            periods.append(int(vals[j]))
        if len(gaps):
            periods.extend(int(np.quantile(gaps, q)) for q in (0.25, 0.5, 0.75))
    if time.monotonic() < deadline:
        spectrum = np.abs(fft.rfft(mask.astype(float), workers=1))
        lo = 8
        hi = min(len(spectrum)-1, max(lo+1, n//4))
        if hi > lo:
            count = min(8, hi-lo)
            indices = np.argpartition(spectrum[lo:hi], -count)[-count:] + lo
            indices = indices[np.argsort(spectrum[indices])[::-1]]
            periods.extend(int(round(n/int(k))) for k in indices)
    del mask
    unique = []
    for p in periods:
        if time.monotonic() >= deadline:
            break
        if 4 <= p <= n//3 and all(abs(p-q) > max(1, p//1000) for q in unique):
            unique.append(p)
    unique = unique[:int(params['period_count'])]
    if not unique:
        unique = [max(4, n//128), max(4, n//256)]
    jobs = []
    for phase in (0.0, 0.5, 0.25):
        for factor in (2, 3):
            for period in unique:
                if time.monotonic() >= deadline:
                    break
                jobs.append((period, factor, phase))
    class Stop(Exception):
        pass
    for period, factor, phase in jobs:
        if time.monotonic() >= deadline:
            break
        p = max(factor, int(round(period/factor))*factor)
        offset = int(phase*p)
        blocks = (n-offset)//p
        if blocks < 2:
            continue
        end = offset+blocks*p
        transformed = f.copy()
        slab = f[offset:end].reshape(blocks, p)
        compressed = slab.reshape(blocks, p//factor, factor).mean(axis=2)
        transformed[offset:end] = np.tile(compressed, (1, factor)).ravel()
        delta = transformed-f
        del compressed, transformed
        if time.monotonic() >= deadline:
            break
        ds = fft.rfft(delta, m, workers=1)
        linear = fft.irfft(2.0*fs*ds, m, workers=1)[:length]
        square = fft.irfft(ds*ds, m, workers=1)[:length]
        del ds
        if time.monotonic() >= deadline:
            break
        coefs = (q0, 2*bilinear(base, linear), bilinear(linear, linear)+2*bilinear(base, square), 2*bilinear(linear, square), bilinear(square, square))
        mass_delta = float(np.sum(delta))
        local = [best_score, 0.0]
        def objective(t):
            if time.monotonic() >= deadline:
                raise Stop
            c = base + t*linear + (t*t)*square
            peak = float(np.max(c))
            numerator = coefs[0] + t*(coefs[1]+t*(coefs[2]+t*(coefs[3]+t*coefs[4])))
            score = numerator / (peak*(1.0+t*mass_delta)**2)
            if score > local[0]:
                local[:] = [score, float(t)]
            return -score
        try:
            for t in (1.0, 0.5, 0.125, 0.025, 0.002, 0.0001):
                if time.monotonic() >= deadline:
                    raise Stop
                objective(t)
            if local[1] != 0.0:
                center = local[1]
                minimize_scalar(objective, bounds=(max(0.0, center*0.3), min(1.0, center*2.5)), method='bounded', options={'maxiter': 12, 'xatol': 1e-9})
        except Stop:
            pass
        if local[1] != 0.0 and time.monotonic() < start+0.77*budget_s:
            candidate = np.maximum(f + local[1]*delta, 0.0)
            score = exact_score(candidate)
            if score > best_score:
                best_score = score
                best = candidate
        del delta, linear, square
    if best is None:
        return init
    return {'values': best.tolist()}
